@media print {
    body {
        width: 210mm;
        height: 297mm;
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    .page-break {
        page-break-before: always;
        /* Forces a page break before the element */
    }

    .footer-note {
        position: fixed;
        bottom: 0;
        left: 0;
        right: 0;
        padding: 10px;
        background-color: #f5f5f5;
        font-size: 12px;
        border-top: 1px solid #ddd;
        text-align: center;
    }

    .content {
        margin: 10mm;
        height: calc(297mm - 40mm);
        overflow: hidden;
        padding: 20px;
        /* Prevent content from overflowing */
        page-break-inside: avoid;
        /* Prevent breaking inside the element */
    }

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        page-break-after: avoid;
        /* Prevent page break after headers */
    }

    p {
        page-break-inside: avoid;
        /* Prevent breaking inside paragraphs */
        orphans: 3;
        /* Minimum number of lines to keep together at the bottom of the page */
        widows: 3;
        /* Minimum number of lines to keep together at the top of the page */
    }
}

